69  _subset2 (hb_subset_plan_t *plan)
    70  {
    71    bool result = true;
    72    hb_blob_t *source_blob = hb_sanitize_context_t ().reference_table<TableType> (plan->source);
    73    const TableType *table = source_blob->as<TableType> ();
    74
    75    hb_tag_t tag = TableType::tableTag;
    76    if (source_blob->data)
    77    {
    78      hb_vector_t<char> buf;
    79      /* TODO Not all tables are glyph-related.  'name' table size for example should not be
    80       * affected by number of glyphs.  Accommodate that. */
    81      unsigned int buf_size = _plan_estimate_subset_table_size (plan, source_blob->length);
    82      DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c initial estimated table size: %u bytes.", HB_UNTAG (tag), buf_size);
    83      if (unlikely (!buf.alloc (buf_size)))
    84      {
    85        DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c failed to allocate %u bytes.", HB_UNTAG (tag), buf_size);
    86        return false;
    87      }
    88    retry:
    89      hb_serialize_context_t serializer ((void *) buf, buf_size);
    90      serializer.start_serialize<TableType> ();
    91      hb_subset_context_t c (plan, &serializer);
    92      bool needed = table->subset (&c);
    93      if (serializer.ran_out_of_room)
    94      {
    95        buf_size += (buf_size >> 1) + 32;
    96        DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c ran out of room; reallocating to %u bytes.", HB_UNTAG (tag), buf_size);
    97        if (unlikely (!buf.alloc (buf_size)))
    98        {
    99          DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c failed to reallocate %u bytes.", HB_UNTAG (tag), buf_size);
   100          return false;
   101        }
   102        goto retry;
   103      }
   104      serializer.end_serialize ();
   105
   106      result = !serializer.in_error ();
   107
   108      if (result)
   109      {
   110        if (needed)
   111        {
   112          hb_blob_t *dest_blob = serializer.copy_blob ();
   113          DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c final subset table size: %u bytes.", HB_UNTAG (tag), dest_blob->length);
   114          result = c.plan->add_table (tag, dest_blob);
   115          hb_blob_destroy (dest_blob);
   116        }
   117        else
   118        {
   119          DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset table subsetted to empty.", HB_UNTAG (tag));
   120        }
   121      }
   122    }
   123    else
   124      DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset sanitize failed on source table.", HB_UNTAG (tag));
   125
   126    hb_blob_destroy (source_blob);
   127    DEBUG_MSG(SUBSET, nullptr, "OT::%c%c%c%c::subset %s", HB_UNTAG (tag), result ? "success" : "FAILED!");
   128    return result;
   129  }
